const { parsers } = require('prettier/parser-babylon')
const PrettierEslint = require('./PrettierEslint')

const prettierEslint = new PrettierEslint()

const preprocess = (text, options) => {
  return prettierEslint.process(text, options)
}

exports.parsers = {
  babel: {
    ...parsers.babel,
    preprocess: parsers.babel.preprocess ? (text, options) => preprocess(parsers.babel.preprocess(text, options), options) : preprocess
  }
}
